import {mountReviews} from './workshop-review-ui.mjs';
import {reviewPlan,reviewSchedule} from './workshop-review.mjs';
import {caseInfo} from './workshop-content.mjs';
import {required,sampleTimes,isIntermittent,snapshot,faultModes} from './workshop-model.mjs';
import {adaptivePlan} from './workshop-adaptive.mjs';
const p=(es,en)=>({es,en});
export const historyKey='mecanica.workshop.challenges.v1';
export const alternate={
 mechanics:{answer:'battery',label:p('Batería con tensión insuficiente bajo carga','Insufficient battery voltage under load'),fix:p('Restablecer el suministro de batería del modelo','Restore the model battery supply'),explain:p('La batería cae a 8 V bajo carga; la caída en masa sigue en 0,15 V. Una caída de masa normal separa este caso de una conexión resistiva. Corregir el suministro recupera 10,8 V y 220 rpm.','Battery voltage falls to 8 V under load; ground drop remains 0.15 V. Normal ground drop distinguishes this case from a resistive connection. Restoring supply recovers 10.8 V and 220 rpm.')},
 electronics:{answer:'gain',label:p('Ganancia configurada demasiado alta','Gain configured too high'),fix:p('Restablecer ganancia 5','Restore gain 5'),explain:p('La entrada es 2 V pico, pero la ganancia 8 solicita 16 V: la salida se limita a 12 V. Restablecer ganancia 5 recupera 10 V sin recorte. No hay evidencia de un chip dañado.','Input is 2 V peak, but gain 8 requests 16 V: output clips at 12 V. Restoring gain 5 recovers 10 V without clipping. This is not evidence of a failed chip.')},
 hydraulics:{answer:'pump',label:p('Caudal de suministro insuficiente','Insufficient supply flow'),fix:p('Restablecer caudal de suministro a 6 L/min','Restore supply flow to 6 L/min'),explain:p('Solo entran 3 L/min y la fuga es cero. Con área de 10 cm² resultan 50 mm/s. El síntoma se parece a una fuga, pero la prueba de caudal distingue las causas. No determina qué pieza del suministro falló.','Only 3 L/min enters and leakage is zero. A 10 cm² area gives 50 mm/s. The symptom resembles leakage, but flow testing distinguishes the causes. It does not identify which supply component failed.')},
 pneumatics:{answer:'compressor',label:p('Presión de suministro insuficiente','Insufficient supply pressure'),fix:p('Restablecer suministro a 4 bar','Restore supply to 4 bar'),explain:p('El suministro es 2 bar y la contrapresión es normal: 0,2 bar. Hay menos fuerza disponible sin obstrucción del escape. Restablecer 4 bar normaliza el modelo; esta prueba no identifica por sí sola un compresor averiado.','Supply is 2 bar and back pressure is normal at 0.2 bar. Available force is lower without an exhaust obstruction. Restoring 4 bar normalises the model; this test alone does not identify a failed compressor.')}
};
export function expectedReading(kind,fault,id,time=.5){const state={kind,fault,time},a=snapshot(state),b=snapshot(state,true);const fields={battery:['loaded'],ground:['drop'],input:['inputPeak','gain'],output:['outputPeak','clipped'],speed:['speed'],flow:['inlet'],leak:['leak'],supply:['supply'],exhaust:['back']}[id];return fields.some(key=>a[key]!==b[key]);}
export function challengeScore(c){return Math.max(0,100-c.wrongDiagnosis*15-c.readings.filter(r=>!r.correct).length*10-c.hints*8);}
export function loadResults(storage){try{const a=JSON.parse(storage.getItem(historyKey)||'[]');return Array.isArray(a)?a.filter(r=>r&&caseInfo[r.kind]&&faultModes.includes(r.fault)&&typeof r.id==='string'&&Number.isFinite(r.score)&&Array.isArray(r.readings)&&r.readings.every(x=>x&&required[r.kind].includes(x.id)&&typeof x.correct==='boolean')&&Number.isFinite(r.wrongDiagnosis)&&Number.isFinite(r.hints)&&Number.isFinite(Date.parse(r.date))).slice(-200):[];}catch{return [];}}
export function saveResult(storage,result){const list=loadResults(storage);if(!list.some(r=>r.id===result.id))list.push(result);storage.setItem(historyKey,JSON.stringify(list.slice(-200)));return list;}
export function mountChallenges(api){
 const $=s=>document.querySelector(s),text=x=>x[api.lang()],el=(tag,content,host)=>{const n=document.createElement(tag);n.textContent=content;host.append(n);return n;};
 const box=document.createElement('section');box.className='challenge-panel';$('#benches').before(box);
 const assessment=document.createElement('div');assessment.id='measurementInterpretation';$('#tests').after(assessment);
 const archive=document.createElement('section');archive.id='challengeHistory';archive.className='challenge-panel';$('main').append(archive);
 let active=null,pending=null,notice=null,saveError=false,results=[];try{results=loadResults(localStorage);}catch{}
 const names={mechanics:p('Mecánica','Mechanics'),electronics:p('Electrónica','Electronics'),hydraulics:p('Hidráulica','Hydraulics'),pneumatics:p('Neumática','Pneumatics')};
 const readingNames={battery:p('Tensión bajo carga','Loaded voltage'),ground:p('Caída de masa (no rpm)','Ground drop (not rpm)'),input:p('Entrada o ganancia','Input or gain'),output:p('Forma y amplitud de salida','Output shape and amplitude'),speed:p('Velocidad','Speed'),flow:p('Caudal de entrada','Inlet flow'),leak:p('Caudal de fuga','Leakage flow'),supply:p('Presión de suministro','Supply pressure'),exhaust:p('Contrapresión (no fuerza ni velocidad)','Back pressure (not force or speed)')};
 const reviews=mountReviews({before:box,results:()=>results,lang:api.lang,kind:api.kind,busy:()=>Boolean(active&&!active.finished),start:entry=>start(entry),name:entry=>{const primary=caseInfo[entry.kind].options[({mechanics:'ground',electronics:'clipping',hydraulics:'leak',pneumatics:'restriction'})[entry.kind]];const label=entry.type==='measurement'?readingNames[entry.id]:entry.id==='combined'?p('Diagnóstico combinado','Combined diagnosis'):entry.id.includes('alternate')?alternate[entry.kind].label:primary;return text(names[entry.kind])+' · '+(entry.id.startsWith('intermittent-')?text(p('Intermitente · ','Intermittent · ')):'')+text(label);}});
 function start(request){const review=reviewSchedule(results).find(e=>e.kind===api.kind&&e.key===request?.key);const bytes=new Uint32Array(1);crypto.getRandomValues(bytes);const plan=review?reviewPlan(results,review,bytes[0]/4294967296):adaptivePlan(results,api.kind,bytes[0]/4294967296),fault=plan.fault;active={id:crypto.randomUUID(),fault,plan,review:review?.key??null,readings:[],wrongDiagnosis:0,hints:0,finished:false};pending=null;notice=null;saveError=false;
  const data={...api.base,options:{...api.base.options,[alternate[api.kind].answer]:alternate[api.kind].label},title:p('Reto sorpresa · '+names[api.kind].es,'Surprise challenge · '+names[api.kind].en),symptom:p('Compara A y B. Dos causas diferentes pueden producir síntomas parecidos. Usa las mediciones para distinguirlas.','Compare A and B. Two different causes can produce similar symptoms. Use measurements to distinguish them.'),guide:[p('Observa ambos bancos con el reloj compartido.','Observe both benches using the shared clock.'),p('Mide e interpreta cada magnitud antes de diagnosticar.','Measure and interpret each quantity before diagnosing.'),p('Corrige la causa y repite las pruebas para guardar el resultado.','Correct the cause and repeat tests to save the result.')],limit:p(api.base.limit.es+' En el reto alternativo cambian las condiciones de suministro o ganancia; las velocidades siguen siendo prescritas. Las causas pueden combinarse o aparecer en ventanas periódicas del reloj de ensayo. El cilindro conserva su posición al cambiar el fallo; con fuerza de avance negativa se representa bloqueo, no retroceso dinámico.',api.base.limit.en+' In the alternative challenge, supply or gain conditions change; speeds remain prescribed. Causes can combine or occur in periodic test-clock windows. The cylinder retains position at fault transitions; negative extension force is represented as a stall, not dynamic back-driving.')};
  if(fault==='alternate'){data.fix=alternate[api.kind].fix;data.explain=alternate[api.kind].explain;}
  const primary=api.base.options[({mechanics:'ground',electronics:'clipping',hydraulics:'leak',pneumatics:'restriction'})[api.kind]],alt=alternate[api.kind];
  data.options.combined=p(primary.es+' + '+alt.label.es,primary.en+' + '+alt.label.en);
  for(const side of ['primary','alternate']){const label=side==='primary'?primary:alt.label;data.options['intermittent-'+side]=p('Intermitente: '+label.es,'Intermittent: '+label.en);}
  if(fault==='combined'){data.fix=p('Corregir ambas causas del modelo','Correct both model causes');data.explain=p('Las dos causas están presentes: '+data.options.combined.es+'. Corregir solo una no basta; esta acción restablece ambas. Compara cada magnitud con A antes y después.','Both causes are present: '+data.options.combined.en+'. Correcting only one is insufficient; this action restores both. Compare each quantity with A before and after.');}
  if(fault.startsWith('intermittent-')){const altFault=fault.endsWith('alternate');data.fix=altFault?alt.fix:api.base.fix;data.explain=p('La causa aparece entre 0,75–1,75 de cada período de 2 unidades del reloj de ensayo. Una lectura normal en 0,5 no la descarta: compara con 1,25. La reparación elimina todas las ventanas del fallo. Causa: '+(altFault?alt.label.es:primary.es)+'.','The cause appears at 0.75–1.75 of each 2-unit test-clock period. A normal reading at 0.5 does not rule it out: compare with 1.25. Repair removes every fault window. Cause: '+(altFault?alt.label.en:primary.en)+'.');}
  api.start(fault,data);
 }
 function render(){box.replaceChildren();assessment.replaceChildren();el('h2',text(p('Retos sorpresa','Surprise challenges')),box);el('p',text(p('Retos adaptativos: causas individuales, combinadas e intermitentes. 100 puntos −15 por diagnóstico incorrecto, −10 por interpretación incorrecta y −8 por pista. Sin penalización por tiempo ni por repetir una medición.','Adaptive challenges: individual, combined and intermittent causes. 100 points −15 per incorrect diagnosis, −10 per incorrect interpretation and −8 per hint. No time penalty or charge for repeating a measurement.')),box);
  const plan=active&&!active.finished?active.plan:adaptivePlan(results,api.kind),levels=[p('Individual','Individual'),p('Combinado','Combined'),p('Intermitente','Intermittent')];
  el('h3',text(p('Nivel recomendado: ','Recommended level: '))+plan.level+' · '+text(levels[plan.level-1]),box);
  if(plan.recentCount)el('p',text(p('Enfoque: ','Focus: '))+text(readingNames[plan.focus])+' · '+text(p('Últimos resultados: ','Recent results: '))+plan.recentCount+' · '+plan.score+'/100 · '+plan.accuracy+'% '+text(p('interpretaciones correctas','correct interpretations')),box);else el('p',text(p('Aún no hay resultados: empieza con causas individuales. No se ha estimado tu dominio.','No results yet: start with individual causes. Your mastery has not been estimated.')),box);
  el('p',text(p('Se priorizan las causas asociadas a tus errores de medición y diagnóstico en los últimos 12 retos de este taller. Para avanzar: al menos 3 resultados, media ≥85, interpretaciones ≥85% y como máximo 1 pista de media en los últimos 5. Tres retos avanzados con media ≥85 abren intermitencias. El nivel baja si estos criterios dejan de cumplirse.','Causes associated with measurement and diagnosis errors in your last 12 challenges in this workshop get higher priority. To advance: at least 3 results, average ≥85, interpretations ≥85%, and at most 1 hint on average in the last 5. Three advanced challenges averaging ≥85 unlock intermittent faults. The level drops if these criteria are no longer met.')),box);
  const btn=el('button',text(p(active&&!active.finished?'Abandonar y sortear otro reto':'Nuevo reto adaptativo',active&&!active.finished?'Abandon and draw another challenge':'New adaptive challenge')),box);btn.id='newChallenge';btn.onclick=start;
  if(active){el('strong',' '+challengeScore(active)+'/100',box);el('p',text(p('Interpreta la magnitud indicada, comparándola con A. Las medidas de velocidad o fuerza auxiliares no cambian la clasificación de una presión o caída de tensión.','Interpret the named quantity against A. Auxiliary speed or force readings do not change the classification of a pressure or voltage drop.')),box);
   const hint=el('button',text(p('Pista','Hint'))+' ('+active.hints+'/2)',box);hint.id='challengeHint';hint.disabled=active.finished||active.hints>=2;hint.onclick=()=>{active.hints++;api.refresh();};
   if(active.hints>0)el('p',text(p('Primero separa el suministro de la respuesta del componente. Un mismo síntoma no demuestra una misma causa.','First separate the supply from the component response. The same symptom does not prove the same cause.')),box);
   if(active.hints>1&&active.plan.level===3)el('p',text(p('Varias magnitudes pueden cambiar juntas. Compara también ambos momentos: una lectura sana no demuestra que el fallo haya desaparecido.','Multiple quantities can change together. Also compare both moments: a healthy reading does not prove the fault has gone away.')),box);
   if(active.hints>1&&active.plan.level===2)el('p',text(p('Comprueba las dos causas por separado. Identificar una no explica necesariamente todas las lecturas.','Check both causes separately. Identifying one does not necessarily explain every reading.')),box);
   if(active.hints>1)el('p',text({mechanics:p('Compara tensión bajo carga y caída de masa: identifica cuál se aparta de A.','Compare loaded voltage and ground drop: identify which differs from A.'),electronics:p('Calcula entrada × ganancia y compara con ±12 V. Identifica si cambió entrada o ganancia.','Calculate input × gain and compare with ±12 V. Identify whether input or gain changed.'),hydraulics:p('Caudal útil = entrada − fuga. Mide ambos términos.','Useful flow = inlet − leakage. Measure both terms.'),pneumatics:p('Distingue presión de suministro baja de contrapresión de escape alta.','Distinguish low supply pressure from high exhaust back pressure.')}[api.kind]),box);
   if(isIntermittent(api.get())){el('p',text(p('Toma todas las mediciones en ambos momentos, antes y después de reparar. El cursor y Reproducir permiten observar la transición; estas pruebas usan instantes repetibles.','Take every measurement at both moments, before and after repair. Use the cursor and Play to observe the transition; these tests use repeatable instants.')),assessment);for(const time of sampleTimes(api.get())){const button=el('button',text(p('Medir en t = ','Measure at t = '))+time,assessment);button.dataset.sample=String(time);button.setAttribute('aria-pressed',String((api.get().sampleTime??.5)===time));button.onclick=()=>{api.get().sampleTime=time;pending=null;api.refresh();};}$('#measureNote').textContent=text(p('La prueba pausa ambos bancos en el momento elegido: 0,5 o 1,25 del reloj de ensayo. Clasifica la lectura de ese instante, no el fallo global.','Each test pauses both benches at the chosen instant: 0.5 or 1.25 on the test clock. Classify that instant’s reading, not the overall fault.'));}
   if(pending&&!active.finished){const question=el('fieldset','',assessment);el('legend',text(readingNames[pending.id])+' · '+text(p('¿Coincide con A?','Does it match A?'))+' · t = '+pending.time,question);for(const [value,label]of [[false,p('Normal','Normal')],[true,p('Anormal','Abnormal')]]){const b=el('button',text(label),question);b.dataset.interpret=String(value);b.onclick=()=>{const {id,time}=pending,correct=value===expectedReading(api.kind,active.fault,id,time);active.readings.push({id,time,correct});pending=null;notice=correct?p('Interpretación correcta.','Correct interpretation.'):p('Revisa la magnitud indicada y el valor de A en el cuaderno. No clasifiques toda la máquina a partir de esa lectura.','Review the named quantity and A’s value in the notebook. Do not classify the whole machine from that reading.');api.refresh();};}}
   if(notice)el('p',text(notice),assessment).setAttribute('role','status');
   const missing=required[api.kind].flatMap(id=>sampleTimes(api.get()).filter(time=>!active.readings.some(r=>r.id===id&&(r.time??.5)===time)).map(time=>({id,time})));
   if(missing.length){el('p',text(p('Falta interpretar: ','Still to interpret: '))+missing.map(({id,time})=>text(readingNames[id])+' @ '+time).join(', '),assessment);$('#confirm').disabled=true;}
   $('#scope').textContent=text(p('Se guardan los retos verificados en este navegador, hasta 200. Cambiar idioma conserva el reto. Recargar o abandonar descarta el reto sin terminar; no se registra como aprobado.','Verified challenges are saved in this browser, up to 200. Changing language preserves the challenge. Reloading or abandoning discards the unfinished challenge; it is not recorded as a pass.'));
   if(!api.get().diagnosed)$('#repair').textContent=text(p('Corregir después de diagnosticar','Correct after diagnosis'));
   if(active.finished)el('p',text(saveError?p('Resultado completado, pero el navegador no permitió guardarlo. Mantén esta página abierta para verlo.','Challenge completed, but browser storage could not save it. Keep this page open to see the result.'):p('Resultado guardado. Revisa tus dificultades abajo.','Result saved. Review your difficulties below.')),box).setAttribute('role','status');
  }
  renderHistory();reviews.render();
 }
 function renderHistory(){archive.replaceChildren();el('h2',text(p('Resultados y puntos a reforzar','Results and areas to practise')),archive);el('p',text(p('Solo retos terminados y verificados. Historial local de este navegador; no se sincroniza entre dispositivos.','Completed and verified challenges only. History is local to this browser; it does not sync between devices.')),archive);
  if(!results.length){el('p',text(p('Completa un reto para empezar tu historial.','Complete a challenge to start your history.')),archive);return;}
  for(const kind of Object.keys(caseInfo)){const rows=results.filter(r=>r.kind===kind);if(!rows.length)continue;const card=el('article','',archive);el('h3',text(names[kind])+' · '+rows.length+' '+text(p('retos','challenges')),card);el('p',text(p('Última nota / anterior / media: ','Latest / previous / average score: '))+rows.at(-1).score+' / '+(rows.at(-2)?.score??'—')+' / '+Math.round(rows.reduce((n,r)=>n+r.score,0)/rows.length),card);
   const stats=required[kind].map(id=>{const a=rows.flatMap(r=>r.readings).filter(r=>r.id===id);return {id,total:a.length,bad:a.filter(r=>!r.correct).length};}).sort((a,b)=>b.bad/Math.max(1,b.total)-a.bad/Math.max(1,a.total));
   for(const x of stats)el('p',text(readingNames[x.id])+': '+x.bad+'/'+x.total+' '+text(p('interpretaciones incorrectas','incorrect interpretations')),card);
   for(const fault of faultModes){const a=rows.filter(r=>r.fault===fault);if(!a.length)continue;const primary=caseInfo[kind].options[({mechanics:'ground',electronics:'clipping',hydraulics:'leak',pneumatics:'restriction'})[kind]],base=fault.includes('alternate')?alternate[kind].label:primary;const label=fault==='combined'?p(primary.es+' + '+alternate[kind].label.es,primary.en+' + '+alternate[kind].label.en):fault.startsWith('intermittent-')?p('Intermitente: '+base.es,'Intermittent: '+base.en):base;el('p',text(label)+': '+a.reduce((n,r)=>n+r.wrongDiagnosis,0)+' '+text(p('diagnósticos incorrectos en ','incorrect diagnoses across '))+a.length+' '+text(p('retos','challenges')),card);}
   const link=el('a',text(p('Practicar este taller →','Practise this workshop →')),card);link.href='workshop.html?case='+kind+'&lang='+api.lang()+'#newChallenge';}
  const list=el('ol','',archive);for(const r of results.slice(-12).reverse())el('li',new Date(r.date).toLocaleString(api.lang())+' · '+text(names[r.kind])+' · '+text(r.fault==='combined'?p('Combinado','Combined'):r.fault.startsWith('intermittent-')?p('Intermitente','Intermittent'):p('Individual','Individual'))+' · '+r.score+'/100 · '+r.hints+' '+text(p('pistas','hints')),list);
 }
 return {render,ready:()=>!active||required[api.kind].every(id=>sampleTimes(api.get()).every(time=>active.readings.some(r=>r.id===id&&(r.time??.5)===time))),reset(){active=null;pending=null;notice=null;},measured(id){if(active&&!active.finished&&!api.get().repaired&&!active.readings.some(r=>r.id===id&&(r.time??.5)===api.get().time))pending={id,time:api.get().time};},diagnosed(status){if(active&&!active.finished&&status==='wrong')active.wrongDiagnosis++;},completed(){if(!active||active.finished)return;active.finished=true;pending=null;const row={id:active.id,kind:api.kind,fault:active.fault,date:new Date().toISOString(),score:challengeScore(active),level:active.plan.level,focus:active.plan.focus,review:active.review,wrongDiagnosis:active.wrongDiagnosis,hints:active.hints,readings:active.readings};try{results=saveResult(localStorage,row);}catch{saveError=true;results=[...results,row];}}};
}
